window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-07951c464316f3a0"]={"versions": [{"id": "FIG-07951c464316f3a0", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Schichtenarchitektur-Diagramm (AUTOSAR Layered Software Architecture Overview) der AUTOSAR Classic Platform. Das Diagramm verortet die Basissoftware (BSW), die Runtime Environment (RTE) und die Application Layer relativ zur zugrundeliegenden Hardware (Mikrocontroller). Im Kontext der Spezifikation AUTOSAR_SWS_DCM hebt die farbige Hinterlegung des Modulblocks „Communication Services“ die funktionale und hierarchische Eingliederung des Diagnostic Communication Manager (DCM) innerhalb der AUTOSAR-Gesamtarchitektur hervor.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert das Gesamtsystem in vertikale Domänen und horizontale Abstraktionsschichten:</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Oberste Ebene zur Ausführung der Software-Komponenten (SWCs).</li>\n<li><strong>RTE (Runtime Environment)</strong>: Durchgehende Abstraktions- und Vermittlungsschicht zwischen Applikationsebene und Basissoftware.</li>\n<li><strong>Services Layer</strong>: Oberste BSW-Ebene mit den Funktionsblöcken <em>System Services</em> (L-förmig, linker Randbereich), <em>Memory Services</em> und <em>Communication Services</em> (hervorgehoben; Beherbergung von DCM, ComM, PduR).</li>\n<li><strong>ECU Abstraction Layer</strong>: Mittlere BSW-Ebene mit <em>Onboard Dev. Abstraction</em>, <em>Memory HW Abstraction</em>, <em>COM HW Abstraction</em> sowie der vertikal übergreifenden <em>I/O HW Abstraction</em>.</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL)</strong>: Unterste BSW-Ebene mit <em>Microcontroller Drivers</em>, <em>Memory Drivers</em>, <em>Communication Drivers</em> und <em>I/O Drivers</em>.</li>\n<li><strong>Complex Drivers (CDD)</strong>: Schichtenübergreifender Pfad am rechten Rand, der die RTE direkt mit der Hardware verbindet und Abstraktionsschichten für zeitkritische oder proprietäre Funktionen umgeht.</li>\n<li><strong>Microcontroller (µC)</strong>: Hardware-Ebene als Basis des Stacks.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen sind implizit durch Schichtgrenzen und vertikale Säulenstrukturen (z. B. Communication Services → COM HW Abstraction → Communication Drivers → µC) sowie horizontale Anbindungen an die System Services und RTE definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält die Darstellung keine Sequenzabläufe, Zustandsmaschinen oder Nachrichtendiagramme. Aus der Schichtung ergibt sich für Diagnoseabläufe des DCM folgender Kontroll- und Datenfluss: Diagnoseanfragen treffen über busbasierte Kommunikationskanäle am Mikrocontroller ein, passieren die <em>Communication Drivers</em> und die <em>COM HW Abstraction</em> (Interface-Module wie CanIf/LinIf/FrIf) und gelangen über den PDU-Router in die <em>Communication Services</em> an den DCM. Der DCM dekodiert und verarbeitet den Diagnosedienst (UDS/OBD), interagiert horizontal mit den <em>System Services</em> (z. B. DEM für Fehlercodespeicher, DET für Entwicklungsfehler, BswM/ECUM für Zustandsverwaltung) und vertikal über die RTE mit Anwendungs-SWCs (z. B. für Routine-Control oder IO-Control) bzw. leitet Antwort-PDUs zurück in den Kommunikationspfad.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Vorgabe für die Modulintegration: Der DCM ist zwingend als Softwaremodul der Schicht <em>Communication Services</em> zu implementieren. Direkte Schnittstellen zur Applikationsebene dürfen ausschließlich über standardisierte RTE-Ports realisiert werden; direkte Durchgriffe auf unterlagerte Treiberstufen (MCAL) oder Bus-Hardware sind unzulässig und müssen über die Schnittstellen des PDU-Routers sowie standardisierte BSW-APIs abgewickelt werden. Das Schaubild dient Integratoren und BSW-Entwicklern als normative Zuordnungsrichtlinie für Abhängigkeiten und Modulschichtungen.</p>"}, {"id": "FIG-98189d224f6fb2e4", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Schichtenarchitektur-Diagramm (AUTOSAR Layered Software Architecture Overview) der AUTOSAR Classic Platform. Das Diagramm verortet die Basissoftware (BSW), die Runtime Environment (RTE) und die Application Layer relativ zur zugrundeliegenden Hardware (Mikrocontroller). Im Kontext der Spezifikation AUTOSAR_SWS_DCM hebt die farbige Hinterlegung des Modulblocks „Communication Services“ die funktionale und hierarchische Eingliederung des Diagnostic Communication Manager (DCM) innerhalb der AUTOSAR-Gesamtarchitektur hervor.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert das Gesamtsystem in vertikale Domänen und horizontale Abstraktionsschichten:</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Oberste Ebene zur Ausführung der Software-Komponenten (SWCs).</li>\n<li><strong>RTE (Runtime Environment)</strong>: Durchgehende Abstraktions- und Vermittlungsschicht zwischen Applikationsebene und Basissoftware.</li>\n<li><strong>Services Layer</strong>: Oberste BSW-Ebene mit den Funktionsblöcken <em>System Services</em> (L-förmig, linker Randbereich), <em>Memory Services</em> und <em>Communication Services</em> (hervorgehoben; Beherbergung von DCM, ComM, PduR).</li>\n<li><strong>ECU Abstraction Layer</strong>: Mittlere BSW-Ebene mit <em>Onboard Dev. Abstraction</em>, <em>Memory HW Abstraction</em>, <em>COM HW Abstraction</em> sowie der vertikal übergreifenden <em>I/O HW Abstraction</em>.</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL)</strong>: Unterste BSW-Ebene mit <em>Microcontroller Drivers</em>, <em>Memory Drivers</em>, <em>Communication Drivers</em> und <em>I/O Drivers</em>.</li>\n<li><strong>Complex Drivers (CDD)</strong>: Schichtenübergreifender Pfad am rechten Rand, der die RTE direkt mit der Hardware verbindet und Abstraktionsschichten für zeitkritische oder proprietäre Funktionen umgeht.</li>\n<li><strong>Microcontroller (µC)</strong>: Hardware-Ebene als Basis des Stacks.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen sind implizit durch Schichtgrenzen und vertikale Säulenstrukturen (z. B. Communication Services → COM HW Abstraction → Communication Drivers → µC) sowie horizontale Anbindungen an die System Services und RTE definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält die Darstellung keine Sequenzabläufe, Zustandsmaschinen oder Nachrichtendiagramme. Aus der Schichtung ergibt sich für Diagnoseabläufe des DCM folgender Kontroll- und Datenfluss: Diagnoseanfragen treffen über busbasierte Kommunikationskanäle am Mikrocontroller ein, passieren die <em>Communication Drivers</em> und die <em>COM HW Abstraction</em> (Interface-Module wie CanIf/LinIf/FrIf) und gelangen über den PDU-Router in die <em>Communication Services</em> an den DCM. Der DCM dekodiert und verarbeitet den Diagnosedienst (UDS/OBD), interagiert horizontal mit den <em>System Services</em> (z. B. DEM für Fehlercodespeicher, DET für Entwicklungsfehler, BswM/ECUM für Zustandsverwaltung) und vertikal über die RTE mit Anwendungs-SWCs (z. B. für Routine-Control oder IO-Control) bzw. leitet Antwort-PDUs zurück in den Kommunikationspfad.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Vorgabe für die Modulintegration: Der DCM ist zwingend als Softwaremodul der Schicht <em>Communication Services</em> zu implementieren. Direkte Schnittstellen zur Applikationsebene dürfen ausschließlich über standardisierte RTE-Ports realisiert werden; direkte Durchgriffe auf unterlagerte Treiberstufen (MCAL) oder Bus-Hardware sind unzulässig und müssen über die Schnittstellen des PDU-Routers sowie standardisierte BSW-APIs abgewickelt werden. Das Schaubild dient Integratoren und BSW-Entwicklern als normative Zuordnungsrichtlinie für Abhängigkeiten und Modulschichtungen.</p>"}], "trans": [{"from": "FIG-07951c464316f3a0", "to": "FIG-98189d224f6fb2e4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
